.manga-crew {
  width: 76px;
  height: 100px;
  position: relative;
  color: #151515;
}

.manga-crew i {
  position: absolute;
  display: block;
  box-sizing: border-box;
}

.manga-head {
  left: 9px;
  top: 10px;
  width: 58px;
  height: 60px;
  border: 5px solid #151515;
  border-radius: 48% 52% 45% 48%;
  background: white;
  z-index: 2;
  transform-origin: 50% 90%;
}

.manga-head::after {
  content: "";
  position: absolute;
  left: 12px;
  bottom: -5px;
  width: 26px;
  height: 9px;
  background: white;
}

.manga-body {
  left: 8px;
  top: 60px;
  width: 65px;
  height: 43px;
  background: #151515;
  z-index: 1;
  clip-path: polygon(
    27% 0,
    68% 0,
    100% 0,
    95% 16%,
    77% 35%,
    78% 100%,
    53% 75%,
    39% 77%,
    13% 100%,
    14% 39%,
    0 29%,
    0 17%
  );
}

.manga-body::after {
  content: "";
  position: absolute;
  inset: 4px;
  background: white;
  clip-path: polygon(
    26% 0,
    69% 0,
    98% 0,
    72% 32%,
    72% 92%,
    53% 66%,
    36% 70%,
    20% 91%,
    21% 32%,
    3% 23%,
    3% 18%
  );
}

.manga-reaction {
  top: 0;
  left: 61px;
  width: 28px;
  height: 29px;
  z-index: 3;
}

.manga-reaction > i {
  width: 5px;
  height: 15px;
  border-radius: 4px;
  background: var(--manga-accent, #f47b45);
}

.manga-reaction > i:nth-child(1) {
  left: 0;
  top: 0;
}

.manga-reaction > i:nth-child(2) {
  left: 13px;
  top: 5px;
  transform: rotate(33deg);
}

.manga-reaction > i:nth-child(3) {
  left: 22px;
  top: 20px;
  height: 12px;
  transform: rotate(88deg);
}

.manga-clapper {
  left: 42px;
  top: 42px;
  width: 32px;
  height: 24px;
  border: 2px solid currentColor;
  background: #fff;
  transform: rotate(-5deg);
}

.manga-clapper::after {
  content: "";
  position: absolute;
  left: 5px;
  right: 5px;
  top: 11px;
  height: 2px;
  background: currentColor;
}

.manga-clapper > i {
  left: -2px;
  top: -12px;
  width: 32px;
  height: 10px;
  border: 2px solid currentColor;
  background: repeating-linear-gradient(45deg, #151515 0 4px, #fff 4px 8px);
  transform: rotate(-18deg);
  transform-origin: bottom left;
}

.manga-camera-prop {
  left: 42px;
  top: 40px;
  width: 26px;
  height: 19px;
  border: 2px solid currentColor;
  background: white;
  border-radius: 3px;
}

.manga-reel {
  top: -14px;
  width: 13px;
  height: 13px;
  border: 2px solid currentColor;
  border-radius: 50%;
  background: white;
}

.manga-reel-left {
  left: -1px;
}

.manga-reel-right {
  right: -1px;
}

.manga-camera-lens {
  left: 23px;
  top: 1px;
  width: 10px;
  height: 13px;
  border: 2px solid currentColor;
  clip-path: polygon(0 25%, 100% 0, 100% 100%, 0 75%);
  background: #fff;
}

.manga-tripod {
  top: 17px;
  left: 10px;
  height: 28px;
  width: 2px;
  background: currentColor;
}

.manga-tripod::before,
.manga-tripod::after {
  content: "";
  position: absolute;
  top: 9px;
  width: 2px;
  height: 22px;
  background: currentColor;
  transform-origin: top;
}

.manga-tripod::before {
  transform: rotate(30deg);
}

.manga-tripod::after {
  transform: rotate(-30deg);
}

.manga-stage-box {
  left: 38px;
  top: 40px;
  width: 35px;
  height: 28px;
  border: 2px solid currentColor;
  background: repeating-linear-gradient(45deg, #fff 0 5px, #ddd 5px 6px);
}

.manga-crew .manga-clapper {
  left: 60px;
  top: 72px;
}

.manga-crew .manga-stage-box {
  left: 60px;
  top: 72px;
}

.manga-crew .manga-camera-prop {
  left: 60px;
  top: 68px;
}

.manga-light-prop {
  left: 62px;
  top: 12px;
  width: 35px;
  height: 90px;
}

.manga-light-stand {
  left: 16px;
  top: 20px;
  height: 66px;
  border-left: 3px solid #151515;
}

.manga-light-stand::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: -14px;
  width: 26px;
  border-bottom: 3px solid #151515;
}

.manga-light-head {
  top: 0;
  width: 28px;
  height: 23px;
  border: 3px solid #151515;
  border-radius: 5px;
  background: white;
  transform: rotate(-25deg);
}

.manga-light-beam {
  display: none !important;
  top: -23px;
  left: -42px;
  width: 50px;
  height: 60px;
  background: repeating-linear-gradient(0deg, transparent 0 6px, #15151522 6px 7px);
  clip-path: polygon(100% 60%, 0 0, 0 100%);
}

.manga-pencil-prop {
  left: 63px;
  top: 50px;
  width: 9px;
  height: 53px;
  border: 2px solid #151515;
  background: white;
  transform: rotate(30deg);
}

.manga-pencil-prop::after {
  content: "";
  position: absolute;
  left: -2px;
  bottom: -12px;
  border-left: 4.5px solid transparent;
  border-right: 4.5px solid transparent;
  border-top: 11px solid #151515;
}

.manga-headphones-prop {
  z-index: 4;
  left: 7px;
  top: 13px;
  width: 62px;
  height: 37px;
  border: 4px solid #151515;
  border-bottom: 0;
  border-radius: 40px 40px 0 0;
}

.manga-headphones-prop::before,
.manga-headphones-prop::after {
  content: "";
  position: absolute;
  top: 19px;
  width: 8px;
  height: 16px;
  background: #151515;
  border-radius: 3px;
}

.manga-headphones-prop::before {
  left: -6px;
}

.manga-headphones-prop::after {
  right: -6px;
}

.manga-sound-prop {
  left: 56px;
  top: 72px;
  width: 35px;
  height: 27px;
  border: 3px solid #151515;
  background: white;
  transform: rotate(-8deg);
}

.manga-sound-prop i {
  top: 5px;
  height: 12px;
  border-left: 2px solid #151515;
}

.manga-sound-prop i:nth-child(1) {
  left: 6px;
}

.manga-sound-prop i:nth-child(2) {
  left: 14px;
  top: 2px;
}

.manga-sound-prop i:nth-child(3) {
  left: 22px;
}

.manga-crew[data-reacting="false"] .manga-reaction { display: none; }
.manga-crew[data-working="true"] .manga-light-beam { display: block !important; }
